'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []], ['\uFEFF', []], ['\n', [['']]], ['\r\n', [['']]],
  ['\n\n', [[''], ['']]], ['\r\r', [[''], ['']]],
  ['a\r\nb\rc\nd\r\n', [['a'], ['b'], ['c'], ['d']]],
  [',,', [['', '', '']]], ['""', [['']]], ['""\n', [['']]],
  ['a,,b,\n', [['a', '', 'b', '']]],
  ['a"b,c"d', [['a"b', 'c"d']]],
  ['"a,b","say ""hi"""\r\n', [['a,b', 'say "hi"']]],
  ['"a\r\nb\rc\nd",z\n', [['a\r\nb\rc\nd', 'z']]],
  ['""""', [['"']]], ['""""""', [['""']]],
  ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]], ['😀,"😃"', [['😀', '😃']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\t', [['a', 'b', '']], { delimiter: '\t' }],
  ['a\uD83Db', [['a', 'b']], { delimiter: '\uD83D' }],
  ['a\uFEFFb', [['ab']], { delimiter: '\uFEFF' }],
];

test('grammar remains identical at every two-chunk split and at code-unit boundaries', () => {
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser(options);
      const actual = parser.push('');
      actual.push(...parser.push(text.slice(0, split)));
      assert.deepEqual(parser.push(''), []);
      actual.push(...parser.push(text.slice(split)), ...parser.end());
      assert.deepEqual(actual, expected, JSON.stringify({ text, split }));
      assert.deepEqual(parser.end(), []);
      assert.throws(() => parser.push(''), Error);
    }
    const parser = createParser(options);
    const actual = [];
    for (let i = 0; i < text.length; i++) actual.push(...parser.push(text[i]));
    actual.push(...parser.end());
    assert.deepEqual(actual, expected);
  }
});

test('records emit at CR immediately without duplicate LF records or later mutation', () => {
  const parser = createParser({ header: true });
  const first = parser.push('a,b\r');
  assert.deepEqual(first, [['a', 'b']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\n"c\r'), []);
  assert.deepEqual(parser.push('\nd",e\r'), [['c\r\nd', 'e']]);
  assert.deepEqual(parser.push('\n\n'), [['']]);
  assert.deepEqual(parser.push('tail,'), []);
  assert.deepEqual(parser.end(), [['tail', '']]);
  assert.deepEqual(first, [['a', 'b']]);
  assert.throws(() => parser.push('more'), Error);
});

test('syntax errors identify physical lines across every split', () => {
  for (const [text, line] of [
    ['"a"x', 1], ['"a" ', 1], ['"a"\t', 1],
    ['"a\r\nb"x', 2], ['a\r\n"b\rc\nd"x', 4],
    ['"a\r\n""b"x', 2], ['"', 1], ['"a\r', 2],
    ['"a\r\n', 2], ['"a\n\rb', 3], ['a\r\n"b\rc\nd', 4],
    ['"""', 1],
  ]) {
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser();
      assert.throws(() => {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
        parser.end();
      }, error => error instanceof SyntaxError &&
        new RegExp(`line ${line}\\b`).test(error.message));
    }
  }
  assert.throws(() => createParser().push('"closed"x'), SyntaxError);
  const parser = createParser();
  assert.deepEqual(parser.push('"open'), []);
  assert.throws(() => parser.end(), SyntaxError);
});

test('delimiter and chunk validation, empty input, and parser independence', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, false, {}, [], new String(',')]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  for (const value of [undefined, null, 1, false, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => parser.push(value), TypeError);
  }
  assert.deepEqual(parser.push('\uFEFF'), []);
  assert.deepEqual(parser.end(), []);
  assert.deepEqual(parser.end(), []);
  const a = createParser();
  const b = createParser({ delimiter: ';' });
  assert.deepEqual(a.push('"first'), []);
  assert.deepEqual(b.push('x;y\n'), [['x', 'y']]);
  assert.deepEqual(a.push(' second"\n'), [['first second']]);
  assert.deepEqual(a.end(), []);
  assert.deepEqual(b.end(), []);
});

test('header conversion keeps collisions, special keys, padding and helper non-mutation', () => {
  const result = parse('x,x,x_2,x,__proto__,constructor,toString\na,b,c,d,p,k,t\nshort\n', { header: true });
  assert.deepEqual(Object.keys(result[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString']);
  assert.deepEqual(Object.values(result[0]), ['a', 'b', 'c', 'd', 'p', 'k', 't']);
  assert.deepEqual(Object.values(result[1]), ['short', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(result[0]), Object.prototype);
  for (const name of Object.keys(result[0])) {
    const property = Object.getOwnPropertyDescriptor(result[0], name);
    assert.equal(property.enumerable, true);
    assert.equal(property.writable, true);
    assert.equal('value' in property, true);
  }
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('only,header\n', { header: true }), []);
  const rows = Object.freeze([Object.freeze(['one']), Object.freeze(['two', 'three', 'extra'])]);
  const header = Object.freeze(['a', 'b']);
  const options = Object.freeze({ header });
  assert.deepEqual(toObjects(rows, options), [{ a: 'one', b: '' }, { a: 'two', b: 'three' }]);
  assert.deepEqual(rows, [['one'], ['two', 'three', 'extra']]);
  assert.deepEqual(header, ['a', 'b']);
  assert.deepEqual(toObjects(rows, { header: [] }), [{}, {}]);
});

